var n=`1136-caesar-salad`;var a=`world-1136`;var t=`US`;var s=`northern-america`;var r=4;var o=21;var l={en:`Caesar Salad`,ua:`Салат «Цезар»`};var d={en:`Caesar Salad is a dish from United States prepared with white bread, garlic, pasteurized liquid egg, anchovy fillets. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Салат «Цезар», страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: білий хліб, часник, пастеризована рідка яєчна маса, філе анчоусів. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Toast these ingredients over medium heat for about 7 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 7 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:7,i:[[`white-bread`,140,`g`],[`olive-oil`,30,`ml`],[`garlic`,2,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`pasteurized-liquid-egg`,40,`ml`],[`anchovy-fillets`,30,`g`],[`lemon-juice`,45,`ml`],[`dijon-mustard`,12,`g`],[`olive-oil`,80,`ml`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:5,i:[[`romaine-lettuce`,420,`g`],[`parmigiano-reggiano`,90,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-black-pepper`,4,`g`]]}];var m={slug:n,id:a,country:`US`,region:s,servings:4,minutes:21,title:l,text:d,steps:g};export{t as country,m as default,a as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,l as title};